const vardisIcon='<svg class="vardis-symbol" role="img" aria-label="ヴァルディス" viewBox="0 0 32 42" focusable="false"><path d="M7 2C8 9 10 18 11 25L14 39M25 5C26 9 23 13 23 16C20 24 17 32 14 39M2 14C10 12 18 16 28 15M4 22C12 21 22 21 30 23"/></svg>';
const allDefs=()=>[...root.WCA_COMPANIES,...specialCompanies];
const blankTrade=()=>({exportCard:{name:'',offers:[]},businessDeals:[]});
const debugTrade=()=>({exportCard:{name:'公式ルール例',offers:[{resource:'food',quantity:3,revenue:25},{resource:'food',quantity:7,revenue:55},{resource:'health',quantity:2,revenue:10},{resource:'health',quantity:6,revenue:35},{resource:'luxury',quantity:4,revenue:25},{resource:'luxury',quantity:8,revenue:45},{resource:'education',quantity:3,revenue:20},{resource:'education',quantity:5,revenue:35}]},businessDeals:[{name:'公式ルール例',food:0,luxury:8,cost:30,tariffA:16,tariffB:8}]});
const blank=()=>({version:4,participants:{Working:'automa',Capitalist:'human',Middle:'absent',State:'absent'},companies:{},personal:{},common:{values:{},unemployed:{},tokens:{demonstration:false}},trade:blankTrade()});
const clone=x=>JSON.parse(JSON.stringify(x));
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const opts=(obj,current)=>Object.entries(obj).map(([k,v])=>`<option value="${esc(k)}" ${k===current?'selected':''}>${esc(v)}</option>`).join('');
function check(ok,message){if(!ok)throw Error(message);}
function numbers(obj,keys){check(obj&&typeof obj==='object'&&!Array.isArray(obj),'数値記録が不正です');for(const [k,v] of Object.entries(obj))check(keys.includes(k)&&(v===null||Number.isSafeInteger(v)&&v>=0),'不正な項目または数値：'+k);}
function effective(def,c){return c?.slotProfile==='base-v1.2-initial'?{...def,workers:def.workers.slice(0,2)}:def;}
function companyDef(id){return allDefs().find(x=>x.id===id);}
function workingWorkerCount(r){return Object.values(r.common?.unemployed?.Working||{}).reduce((n,x)=>n+Number(x||0),0)+Object.values(r.companies||{}).reduce((n,c)=>n+(c.status==='built'?c.slots.filter(x=>x.owner==='Working').length:0),0)+Object.values(r.personal?.Working?.unions||{}).filter(Boolean).length;}
function workingPopulation(count){const n=Math.max(0,Number(count)||0);if(n<=11)return 3;if(n<=14)return 4;if(n<=17)return 5;if(n<=20)return 6;if(n<=23)return 7;if(n<=26)return 8;if(n<=29)return 9;return 10;}
