  if(effect==='payCapitalistForVp'){const cost=Number(plan.cost||20);check(w.cash>=cost,'特殊アクションの支払い資金が足りません');w.cash-=cost;cap.revenue=Number(cap.revenue||0)+cost;w.vp=Number(w.vp||0)+Number(plan.vp||5);}
