function applyCapitalistBuild(records,id,value,common,payment){const r=clone(records),d=companyDef(id);check(d?.class==='Capitalist'&&r.companies[id]?.status==='market','資本家の市場にある企業を選んでください');check(Object.entries(r.companies).filter(([companyId,c])=>companyDef(companyId)?.class==='Capitalist'&&c.status==='built').length<12,'資本家企業は12社までです');company(value,id);check(value.status==='built','設立後の企業状態が不正です');const occupied=value.slots.filter(x=>x.owner!=='empty'),automated=d.workers.length===0||d.tags?.includes('Automated');check(!occupied.length||occupied.length===value.slots.length,'設立時の労働者は全スロットへ同時に配置してください');check(!occupied.length||occupied.every(x=>x.committed),'設立時に配置する労働者は全員誓約中です');check(value.operating===((automated||occupied.length)?'yes':'no'),'設立直後の操業状態が不正です');const expected=clone(r.common.unemployed);for(let i=0;i<value.slots.length;i++){const slot=value.slots[i];if(slot.owner==='empty')continue;check(workerFits(d.workers[i],slot.owner,slot.skill,d.class),'スロットに配置できない労働者です');check(Number(expected?.[slot.owner]?.[slot.skill]||0)>0,'失業労働者が足りません');expected[slot.owner][slot.skill]--;}for(const owner of ['Working','Middle'])for(const skill of Object.keys(skills))check(Number(common?.unemployed?.[owner]?.[skill]||0)===Number(expected?.[owner]?.[skill]||0),'失業労働者の更新が一致しません');const capitalistCost=payment?Number(payment.capitalistCost):Number(d.cost),stateCost=payment?Number(payment.stateCost||0):0;check(Number.isSafeInteger(capitalistCost)&&capitalistCost>=0&&Number.isSafeInteger(stateCost)&&stateCost>=0&&capitalistCost+stateCost===Number(d.cost),'設立費用の分担が不正です');payCapitalist(r.personal.Capitalist.values,capitalistCost);if(stateCost)payMandatory(r.personal.State.values,stateCost);r.companies[id]=clone(value);r.common=clone(common);return validate(r);}
function applyCapitalistAutomaBuild(records,plan,laborPolicy,bonusType){const d=companyDef(plan?.companyId);check(plan?.action==='BC'&&d?.class==='Capitalist','企業の設立計画が不正です');check((plan.bonusType||null)===(bonusType||null),'企業設立ボーナスがAIカードと一致しません');const expectedState=bonusType==='halfBuild'&&['Food','Luxury'].includes(d.industry)?Math.floor(Number(d.cost||0)/2):0;check(Number(plan.stateCost||0)===expectedState&&Number(plan.capitalistCost)===Number(d.cost)-expectedState,'設立費用のボーナスが不正です');const hasWage=Object.keys(d.wages||{}).length>0,wage=hasWage?({A:'L3',B:'L2',C:'L1'})[laborPolicy]:'unknown';check(plan.wage===wage,'最低賃金の設定が不正です');const slots=clone(plan.slots||[]),automated=d.workers.length===0||d.tags?.includes('Automated'),occupied=slots.filter(x=>x.owner!=='empty');check(slots.length===d.workers.length,'企業スロット数が不正です');check(Boolean(plan.operating)===(automated||occupied.length===slots.length&&occupied.length>0),'操業状態が不正です');const common=clone(records.common);for(let i=0;i<slots.length;i++){const slot=slots[i];if(slot.owner==='empty')continue;check(workerFits(d.workers[i],slot.owner,slot.skill,d.class),'スロットに配置できない労働者です');check(slot.committed,'設立時の労働者は誓約中です');check(Number(common.unemployed?.[slot.owner]?.[slot.skill]||0)>0,'失業労働者が足りません');common.unemployed[slot.owner][slot.skill]--;}const value={status:'built',wage,operating:plan.operating?'yes':'no',machinery:false,strike:false,note:'',slots};return applyCapitalistBuild(records,d.id,value,common,{capitalistCost:Number(plan.capitalistCost),stateCost:expectedState});}
function applyCapitalistSell(records,id){const r=clone(records),d=companyDef(id),c=r.companies[id];check(d?.class==='Capitalist'&&c?.status==='built','売却できる資本家企業ではありません');check(!c.slots.some(x=>x.committed),'誓約中の労働者がいる企業は売却できません');for(const slot of c.slots)if(['Working','Middle'].includes(slot.owner))r.common.unemployed[slot.owner][slot.skill]=Number(r.common.unemployed[slot.owner][slot.skill]||0)+1;r.personal.Capitalist.values.revenue=Number(r.personal.Capitalist.values.revenue||0)+Number(d.cost);r.companies[id]=emptyCompany(d,'discarded');return validate(r);}
