function applyCapitalistExport(records,resource,qty,revenue){const r=clone(records),cap=r.personal.Capitalist.values;check(['food','luxury','health','education'].includes(resource),'輸出する商品が不正です');qty=Number(qty);revenue=Number(revenue);check(Number.isSafeInteger(qty)&&qty>0&&Number(cap[resource]||0)>=qty,'輸出する在庫が足りません');check(Number.isSafeInteger(revenue)&&revenue>=0,'輸出収入が不正です');cap[resource]-=qty;cap.revenue=Number(cap.revenue||0)+revenue;return validate(r);}
