function maybeOpenSetupDialog(r,force=false){document.getElementById('setupWelcome')?.remove();if(!force&&(r.setup||localStorage.getItem(SETUP_WELCOME_KEY)==='seen'))return;const dialog=document.createElement('dialog');dialog.id='setupWelcome';dialog.setAttribute('aria-labelledby','setupWelcomeTitle');dialog.innerHTML=`<div class="dialog-heading"><span class="eyebrow">${force?'新しいゲーム':'最初の1回だけ'}</span><h2 id="setupWelcomeTitle">${force?'新しいゲームを始めますか？':'ゲームの初期状態を入れますか？'}</h2><p>${force?'現在の記録と操作履歴を破棄し、すべて初期状態に戻します。':'共通盤面と個人ボードを2人用に準備します。'}</p></div>${welcomeSetupMarkup(force)}`;document.body.append(dialog);dialog.addEventListener('cancel',e=>{e.preventDefault();if(force){dialog.close();dialog.remove();}});document.getElementById('setupWelcomeLater').onclick=()=>{if(!force)localStorage.setItem(SETUP_WELCOME_KEY,'seen');dialog.close();dialog.remove();};const form=document.getElementById('setupWelcomeForm'),tradeSection=document.getElementById('setupWelcomeTrade'),showTrade=()=>{tradeSection.hidden=new FormData(form).get('automaClass')!=='Capitalist';};form.querySelectorAll('[name=automaClass]').forEach(x=>x.onchange=showTrade);showTrade();document.getElementById('setupDebug').onclick=()=>{document.getElementById('setupWelcomeImmigrant').value='Gray';const choices=root.WCA_COMPANIES.filter(d=>!d.tags.includes('Initial_Setup')).map(d=>d.id);for(let i=choices.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[choices[i],choices[j]]=[choices[j],choices[i]];}dialog.querySelectorAll('[data-welcome-market]').forEach((select,i)=>select.value=choices[i]);const sample=debugTrade(),add=form.querySelector('[data-add-trade-offer]');while(form.querySelectorAll('.trade-offer').length<sample.exportCard.offers.length)add.click();form.elements.exportName.value=sample.exportCard.name;form.querySelectorAll('.trade-offer').forEach((row,i)=>{const offer=sample.exportCard.offers[i];row.querySelector('[data-trade-resource]').value=offer.resource;row.querySelector('[data-trade-quantity]').value=offer.quantity;row.querySelector('[data-trade-revenue]').value=offer.revenue;});const deal=sample.businessDeals[0],name=form.querySelector('[data-deal-name]'),box=name.closest('fieldset');name.value=deal.name;box.querySelector('[data-deal-food]').value=deal.food;box.querySelector('[data-deal-luxury]').value=deal.luxury;box.querySelector('[data-deal-cost]').value=deal.cost;box.querySelector('[data-deal-tariff-a]').value=deal.tariffA;box.querySelector('[data-deal-tariff-b]').value=deal.tariffB;dirty=true;document.getElementById('tradeDialogError').hidden=true;};bindTradeForm(form,trade=>{const market=[...dialog.querySelectorAll('[data-welcome-market]')].map(x=>x.value).filter(Boolean),immigrant=document.getElementById('setupWelcomeImmigrant').value,automaClass=new FormData(form).get('automaClass')||'Working';try{createSetup(2,immigrant,market);}catch(error){document.getElementById('error').hidden=false;document.getElementById('error').textContent=error.message;return;}localStorage.setItem(SETUP_WELCOME_KEY,'seen');const deck=automaClass==='Capitalist'?root.WCA.randomDeck().filter(id=>root.CCAJudge.CARD_DATA[id]):root.WCA.randomDeck();commit({type:'setup',players:2,immigrant,market,automaClass,deck,...(automaClass==='Capitalist'?{trade}:{}),confirmed:true});},1,()=>new FormData(form).get('automaClass')==='Capitalist');dialog.showModal();}
function resetUi(){dirty=false;selectedCompany='cc_supermarket_init';selectedClass='Working';activeTab='turn';document.activeElement?.blur();document.getElementById('setupWelcome')?.remove();document.getElementById('establishDialog')?.remove();}
const tabInfo={turn:'手番',policy:'政策',companies:'企業と労働者',state:'国家',trade:'輸出入',personal:'個人ボード'};
function ensureTabs(r){let policy=document.getElementById('tab-policy');if(!policy){policy=document.getElementById('tab-common');policy.id='tab-policy';policy.textContent='政策';policy.setAttribute('aria-controls','view-policy');const view=document.getElementById('view-common');view.id='view-policy';view.setAttribute('aria-labelledby','tab-policy');for(const id of ['companies','state','trade']){const b=document.createElement('button');b.id='tab-'+id;b.setAttribute('role','tab');b.setAttribute('aria-controls','view-'+id);b.setAttribute('aria-selected','false');b.tabIndex=-1;b.textContent=tabInfo[id];document.getElementById('tab-personal').before(b);const panel=document.createElement('div');panel.id='view-'+id;panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby','tab-'+id);panel.hidden=true;document.getElementById('view-personal').before(panel);}}const showTrade=['Capitalist','Middle'].some(id=>r.participants[id]==='automa');document.getElementById('tab-trade').hidden=!showTrade;if(!showTrade&&activeTab==='trade')activeTab='policy';}
function visibleTabs(){return Object.keys(tabInfo).filter(id=>!document.getElementById('tab-'+id).hidden);}
function setTab(tab,force=false){if(!force&&!discard())return;dirty=false;activeTab=tab;for(const id of Object.keys(tabInfo)){const b=document.getElementById('tab-'+id),active=id===tab;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;document.getElementById('view-'+id).hidden=!active;}if(!force)render(current,commit);}
function bindTabs(){for(const id of Object.keys(tabInfo)){const b=document.getElementById('tab-'+id);b.onclick=()=>setTab(id);b.onkeydown=e=>{const ids=visibleTabs();if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const here=ids.indexOf(id),next=e.key==='Home'?0:e.key==='End'?ids.length-1:(here+(e.key==='ArrowRight'?1:ids.length-1))%ids.length;setTab(ids[next]);document.getElementById('tab-'+ids[next]).focus();}};}}
function minimumWage(position){return ({A:'L3',B:'L2',C:'L1'})[position]||'L1';}
function policyEffect(id,pos){if(id==='1')return `公共企業 ${pos==='A'?9:pos==='B'?6:3}社`;if(id==='2')return `最低賃金 ${minimumWage(pos)}`;if(id==='3')return `税倍率の基礎値 ${pos==='A'?3:pos==='B'?2:1}`;if(id==='4')return `公共医療 ${pos==='A'?0:pos==='B'?5:10}`;if(id==='5')return `公共教育 ${pos==='A'?0:pos==='B'?5:10}`;if(id==='6')return pos==='A'?'海外市場：食料20（基本10＋関税10）・贅沢品12（基本6＋関税6）':pos==='B'?'海外市場：食料15（基本10＋関税5）・贅沢品9（基本6＋関税3）':'海外市場：食料10・贅沢品6（関税なし）';return `追加移民 ${pos==='A'?0:pos==='B'?1:2}人`;}
function taxMultiplier(p){const base={A:3,B:2,C:1}[p[3]],mods={A:2,B:1,C:0},w=mods[p[4]]+mods[p[5]];return base+(p[3]==='A'?w*2:p[3]==='B'?w:0);}
function policyMarkup(s,r){
 const votes=[['workingVotesOutside','労働者階級'],['capitalistVotesOutside','資本家階級'],['middleVotesOutside','中産階級']],proposals=s.proposals||{};
 return `<section class="panel board-window"><div class="section-heading"><div><span class="eyebrow">COMMON BOARD</span><h2>政策</h2></div><strong class="summary-number">税倍率 ${taxMultiplier(s.positions)}</strong></div><div class="policy-grid">${Object.keys(policyNames).map(id=>{const pos=s.positions[id],bill=proposals[id];return `<article class="policy-card ${bill?'has-bill':''}" data-policy-card="${id}"><span class="policy-number">${id}</span><div><h3>${policyNames[id]}</h3><div class="policy-track" aria-label="現在位置 ${pos}">${['A','B','C'].map(x=>`<span class="${x===pos?'current':''}">${x}</span>`).join('')}</div>${bill?`<div class="bill-status">${bill.proposer==='Working'?'労働者オートマ':'他プレイヤー'}の法案 ${bill.from} → ${bill.target}<strong>投票待ち</strong></div>`:''}<p>${policyEffect(id,pos)}</p></div></article>`;}).join('')}</div><p class="source">法案の提議中も施行位置は変わりません。投票結果を記録すると更新します。</p></section><section class="panel vote-board"><div class="section-heading"><div><span class="eyebrow">VOTING BAG</span><h2>投票駒</h2></div><small>各色25個</small></div><p class="muted">目視できる袋の外の個数を入力します。袋の中は自動計算します。</p><form id="voteForm"><div class="vote-grid">${votes.map(([key,label])=>{const outside=r.common.values?.[key]??null,inside=outside===null?'?':25-outside;return `<label><span>${label}</span><input type="number" data-vote="${key}" min="0" max="25" value="${outside??''}" placeholder="袋の外"><strong>袋の中 ${inside}</strong></label>`;}).join('')}</div><button type="submit">投票駒を保存</button><span class="draft-state"></span></form><p class="source">基本ルールの構成物：各色25個。開始時は袋の中8個、袋の外17個。</p></section>`;
}
function workerToken(slot){if(['empty','unknown'].includes(slot.owner))return `<span class="worker-token empty">${slot.owner==='unknown'?'?':'空'}</span>`;return `<span class="worker-token ${slot.owner.toLowerCase()} ${slot.committed?'committed':''}" title="${classes[slot.owner]}・${skills[slot.skill]}${slot.committed?'・誓約中':''}">${skills[slot.skill].slice(0,1)}${slot.committed?'◆':''}</span>`;}
function displayedWage(def,c,r,s){const fixed=r.participants[def.class]!=='human';return fixed&&Object.keys(def.wages||{}).length?minimumWage(s.positions[2]):c.wage;}
function wageLabel(def,level){if(level==='unknown')return'未確認';const amount=def.wages?.[level];return amount==null?level:`${level}（${amount}）`;}
function companyCard(def,c,r,s){const wage=displayedWage(def,c,r,s);return `<button class="company-card industry-${def.industry.toLowerCase()}" data-company="${def.id}"><span class="company-topline"><span>${industries[def.industry]}</span><span>${statuses[c.status]}</span></span><strong>${esc(def.name_jp)}</strong><span class="company-stats">${Object.keys(def.wages||{}).length?`賃金 ${wageLabel(def,wage)}`:'賃金なし'}${c.strike?' · ストライキ':''}</span><span class="company-workers">${c.slots.length?c.slots.map(workerToken).join(''):'<span class="worker-token automated">自動</span>'}</span><span class="company-output">${def.production.amount??'?'} ${esc(({Influence:'影響力',...industries})[def.production.resource]||def.production.resource)}</span></button>`;}
function companyGroup(id,r,s){const defs=allDefs().filter(d=>d.class===id),cards=defs.filter(d=>r.companies[d.id]?.status==='built');return `<section class="company-zone class-${id.toLowerCase()}"><div class="zone-title"><h2>${classes[id]}</h2><span>${controls[r.participants[id]]}</span></div><div class="company-card-grid">${cards.length?cards.map(d=>companyCard(d,r.companies[d.id]||emptyCompany(d),r,s)).join(''):`<p class="empty-zone">${r.participants[id]==='absent'?'このゲームには参加しません':'設立済みの企業はありません'}</p>`}</div></section>`;}
function companyEditor(r,s){const original=companyDef(selectedCompany)||allDefs()[0],c=r.companies[original.id]||emptyCompany(original),def=effective(original,c),hasWages=Object.keys(def.wages||{}).length>0,locked=r.participants[def.class]!=='human'&&hasWages,wage=displayedWage(def,c,r,s),wageControl=hasWages?`<label>賃金<select name="wage" ${locked?'disabled':''}>${opts({unknown:'未確認',L1:wageLabel(def,'L1'),L2:wageLabel(def,'L2'),L3:wageLabel(def,'L3')},wage)}</select>${locked?`<small>${controls[r.participants[def.class]]}のため政策2に連動</small>`:''}</label>`:'<input type="hidden" name="wage" value="unknown"><p class="muted">賃金なし（自動化企業）</p>';return `<section class="panel company-editor"><details><summary>企業カードを編集 · ${esc(def.name_jp)}</summary><label>企業を選ぶ<select id="companyPick">${allDefs().map(d=>`<option value="${d.id}" ${d.id===def.id?'selected':''}>${classes[d.class]} · ${esc(d.name_jp)}</option>`).join('')}</select></label><form id="companyForm"><div class="grid"><label>状態<select name="status">${opts(statuses,c.status)}</select></label>${wageControl}<label>操業<select name="operating">${opts({unknown:'未確認',yes:'操業中',no:'停止'},c.operating)}</select></label></div><div class="grid"><label><input name="machinery" type="checkbox" ${c.machinery?'checked':''}>機械</label><label><input name="strike" type="checkbox" ${c.strike?'checked':''}>ストライキ</label></div><h3>労働者</h3>${def.workers.map((w,i)=>{const label=w.type==='MiddleClass'?'中産階級 '+skills[w.color]:w.type==='Skilled'?skills[w.color]:'未熟練';return `<fieldset class="worker-slot"><legend>${i+1} · ${label}スロット</legend><div class="grid"><label>階級<select data-owner="${i}">${opts({unknown:'未確認',empty:'空き',Working:'労働者階級',Middle:'中産階級'},c.slots[i].owner)}</select></label><label>技能<select data-skill="${i}">${opts(skills,c.slots[i].skill)}</select></label></div><label><input type="checkbox" data-committed="${i}" ${c.slots[i].committed?'checked':''}>誓約中</label></fieldset>`;}).join('')}<label>メモ<textarea name="note" rows="2">${esc(c.note)}</textarea></label><button type="submit">企業を保存</button><span class="draft-state"></span></form></details></section>`;}
const numeric=(key,label,value)=>`<label>${label}<input type="number" data-number="${key}" min="0" step="1" value="${value??''}" placeholder="未確認"></label>`;
