function stateMarkup(r,s){const state=r.personal.State||{values:{},note:''},v=r.common.values||{},healthPrice={A:0,B:5,C:10}[s.positions[4]],educationPrice={A:0,B:5,C:10}[s.positions[5]];return `<section class="panel state-board"><div class="section-heading"><div><span class="eyebrow">STATE</span><h2>国家</h2></div><div class="treasury"><span>国庫</span><strong>${state.values.cash??'?'}</strong></div></div><div class="product-grid"><article><span>医療</span><strong>${v.health??'?'}</strong><small>価格 ${healthPrice}</small></article><article><span>教育</span><strong>${v.education??'?'}</strong><small>価格 ${educationPrice}</small></article><article><span>影響力</span><strong>${v.influence??'?'}</strong><small>価格 ${v.influencePrice??'?'}</small></article></div><p class="source">国家が供給するのは医療・教育・影響力です。医療は政策4、教育は政策5の現在位置から価格を表示します。</p></section><section class="panel"><details><summary>国家の数量を編集</summary><form id="stateForm"><div class="grid">${numeric('cash','国庫',state.values.cash)}${numeric('loans','貸付金',state.values.loans)}${numeric('health','公共医療',v.health)}${numeric('education','公共教育',v.education)}${numeric('influence','公共の影響力',v.influence)}${numeric('influencePrice','影響力単価',v.influencePrice)}</div><button type="submit">国家を保存</button><span class="draft-state"></span></form></details></section>`;}
function exportOfferRow(offer={resource:'food',quantity:'',revenue:''}){return `<fieldset class="worker-slot trade-offer"><legend>輸出条件</legend><div class="grid"><label>商品<select data-trade-resource>${opts(tradeResources,offer.resource||'food')}</select></label><label>数量<input data-trade-quantity type="number" min="1" step="1" value="${offer.quantity??''}"></label><label>受取額 ${vardisIcon}<input data-trade-revenue type="number" min="0" step="1" value="${offer.revenue??''}"></label></div><button type="button" class="quiet" data-remove-trade-offer>この条件を削除</button></fieldset>`;}
function tradeFormFields(value,dealCount){const trade=tradeData(value),offers=trade.exportCard.offers.length?trade.exportCard.offers:[{resource:'food',quantity:'',revenue:''},{resource:'food',quantity:'',revenue:''}],deals=Array.from({length:dealCount},(_,i)=>trade.businessDeals[i]||{name:'',food:0,luxury:0,cost:0,tariffA:0,tariffB:0});return `<h3>輸出カード</h3><label>カード名・番号<input name="exportName" value="${esc(trade.exportCard.name)}" placeholder="例：輸出カード #1"></label><div data-export-offers>${offers.map(exportOfferRow).join('')}</div><button type="button" class="quiet" data-add-trade-offer>輸出条件を追加</button><h3>商取引カード</h3>${deals.length?deals.map((deal,i)=>`<fieldset class="worker-slot"><legend>${i+1}枚目</legend><label>カード名・番号<input data-deal-name value="${esc(deal.name)}"></label><div class="grid"><label>食料<input data-deal-food type="number" min="0" step="1" value="${deal.food}"></label><label>ぜいたく品<input data-deal-luxury type="number" min="0" step="1" value="${deal.luxury}"></label><label>価格 ${vardisIcon}<input data-deal-cost type="number" min="0" step="1" value="${deal.cost}"></label><label>政策6A 関税 ${vardisIcon}<input data-deal-tariff-a type="number" min="0" step="1" value="${deal.tariffA??0}"></label><label>政策6B 関税 ${vardisIcon}<input data-deal-tariff-b type="number" min="0" step="1" value="${deal.tariffB??0}"></label></div></fieldset>`).join(''):'<p class="muted">政策6Aのため、商取引カードはありません。</p>'}`;}
function readTradeForm(form){const offers=[...form.querySelectorAll('.trade-offer')].flatMap(row=>{const quantity=row.querySelector('[data-trade-quantity]').value,revenue=row.querySelector('[data-trade-revenue]').value;if(quantity===''&&revenue==='')return[];return[{resource:row.querySelector('[data-trade-resource]').value,quantity:Number(quantity),revenue:Number(revenue)}];}),businessDeals=[...form.querySelectorAll('[data-deal-name]')].map(name=>{const box=name.closest('fieldset');return{name:name.value,food:Number(box.querySelector('[data-deal-food]').value),luxury:Number(box.querySelector('[data-deal-luxury]').value),cost:Number(box.querySelector('[data-deal-cost]').value),tariffA:Number(box.querySelector('[data-deal-tariff-a]').value),tariffB:Number(box.querySelector('[data-deal-tariff-b]').value)};});return{exportCard:{name:form.elements.exportName.value,offers},businessDeals};}
function bindTradeForm(form,onSave,dealCount,required=false){const offers=form.querySelector('[data-export-offers]'),mark=()=>{dirty=true;form.querySelector('.draft-state')&&(form.querySelector('.draft-state').textContent='未保存');};form.querySelector('[data-add-trade-offer]').onclick=()=>{offers.insertAdjacentHTML('beforeend',exportOfferRow());bindRemove();mark();};function bindRemove(){form.querySelectorAll('[data-remove-trade-offer]').forEach(button=>button.onclick=()=>{button.closest('.trade-offer').remove();mark();});}bindRemove();form.addEventListener('input',mark);form.onsubmit=e=>{e.preventDefault();try{onSave(tradeData(readTradeForm(form),dealCount,typeof required==='function'?required():required));}catch(error){const box=form.querySelector('#tradeDialogError')||document.getElementById('error');if(box){box.hidden=false;box.textContent=error.message;}}};}
function importPrices(position){return position==='A'?{food:{base:10,tariff:10},luxury:{base:6,tariff:6}}:position==='B'?{food:{base:10,tariff:5},luxury:{base:6,tariff:3}}:{food:{base:10,tariff:0},luxury:{base:6,tariff:0}};}
function tradeMarkup(r,s){const trade=tradeData(r.trade),prices=importPrices(s.positions[6]),dealCount=({A:0,B:1,C:2})[s.positions[6]],offers=trade.exportCard.offers.map(x=>`<li>${tradeResources[x.resource]} ×${x.quantity}：${x.revenue}${vardisIcon}</li>`).join(''),deals=trade.businessDeals.map(x=>`<li>${esc(x.name||'名称未入力')}：食料${x.food}・ぜいたく品${x.luxury}／本体${x.cost}${vardisIcon}・関税A ${x.tariffA??0}${vardisIcon}・B ${x.tariffB??0}${vardisIcon}</li>`).join('');return `<section class="panel"><span class="eyebrow">IMPORT AND EXPORT</span><h2>輸出入</h2><h3>海外市場からの輸入</h3><div class="product-grid"><article><span>食料</span><strong>${prices.food.base+prices.food.tariff}${vardisIcon}</strong><small>本体${prices.food.base}＋関税${prices.food.tariff}</small></article><article><span>ぜいたく品</span><strong>${prices.luxury.base+prices.luxury.tariff}${vardisIcon}</strong><small>本体${prices.luxury.base}＋関税${prices.luxury.tariff}</small></article></div><p class="source">海外市場に在庫はなく、購入できるのは食料とぜいたく品です。価格と関税は政策6${s.positions[6]}に連動します。</p><h3>輸出カード</h3><div class="setup-summary"><strong>${esc(trade.exportCard.name||'未入力')}</strong>${offers?`<ul>${offers}</ul>`:'<br>輸出条件が未入力です。'}</div><h3>商取引カード</h3><div class="setup-summary">${deals?`<ul>${deals}</ul>`:`政策6${s.positions[6]}：${dealCount?`${dealCount}枚を入力してください`:'カードなし'}`}</div></section><section class="panel"><details><summary>輸出入カードを編集</summary><form id="tradeForm">${tradeFormFields(trade,dealCount)}<button type="submit">輸出入カードを保存</button><span class="draft-state"></span></form></details></section>`;}
function openPreparationTrade(value,positions,dealCount,onSave){document.getElementById('preparationTradeDialog')?.remove();const dialog=document.createElement('dialog');dialog.id='preparationTradeDialog';dialog.setAttribute('aria-labelledby','preparationTradeTitle');dialog.innerHTML=`<div class="dialog-heading"><span class="eyebrow">IMPORT AND EXPORT</span><h2 id="preparationTradeTitle">輸出入カードを記録</h2><p>新しい輸出カード1枚と、政策6${positions[6]}に従う商取引カード${dealCount}枚の内容を入力してください。</p></div><form id="preparationTradeForm">${tradeFormFields(value||blankTrade(),dealCount)}<p id="tradeDialogError" class="notice" hidden></p><div class="dialog-actions"><button type="button" id="preparationTradeCancel" class="quiet">戻る</button><button type="submit">カード内容を保存</button></div><span class="draft-state"></span></form>`;document.body.append(dialog);const form=dialog.querySelector('form');bindTradeForm(form,trade=>{dialog.close();dialog.remove();onSave(trade);},dealCount,true);dialog.querySelector('#preparationTradeCancel').onclick=()=>{dialog.close();dialog.remove();};dialog.addEventListener('cancel',e=>{e.preventDefault();dialog.close();dialog.remove();});dialog.showModal();}
